package com.coraline.feast;

import java.util.UUID;
import com.coraline.registry.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class RescueFoundationsGameTests {
    private static ServerPlayer player(GameTestHelper h,boolean other){var l=other?h.getLevel().getServer().getLevel(com.coraline.otherworld.OtherWorld.KEY):h.getLevel();var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RescueQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var s=new VisitData.Scene();s.owner=p.getUUID();s.door=UUID.randomUUID();s.stage=VisitData.Stage.DONE;s.loop.event.putInt("Serial",7);VisitData.get(p.server).scenes.put(s.owner,s);p.getPersistentData().putUUID("CoralineVisitDoor",s.door);return p;}
    private static void clean(ServerPlayer p){VisitData.get(p.server).scenes.remove(p.getUUID());}
    private static ItemStack stone(VisitData.Scene s){var stack=new ItemStack(ModItems.SEEING_STONE.get());stack.getOrCreateTag().putUUID("StoryOwner",s.owner);stack.getTag().putUUID("StoryDoor",s.door);return stack;}
    @GameTest(template="empty") public static void originalKeyCustodyRoundTripsExactTagAndCannotDuplicate(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{h.assertTrue(ParentRescueStory.grantKey(p,s),"No canonical key");ItemStack original=ItemStack.EMPTY;for(var stack:p.getInventory().items)if(ParentRescueStory.key(stack,s)){stack.getOrCreateTag().putString("OriginalFixture","preserve me");original=stack.copy();}h.assertTrue(StoryItemCustody.capture(p,s,"Key",stack->ParentRescueStory.key(stack,s)),"Existing key not captured");h.assertTrue(ItemStack.isSameItemSameTags(original,StoryItemCustody.held(s,"Key")),"Custody fabricated a different key");h.assertTrue(StoryItemCustody.giveBack(p,s,"Key")&&StoryItemCustody.giveBack(p,s,"Key"),"Return not idempotent");int count=0;for(var stack:p.getInventory().items)if(ParentRescueStory.key(stack,s)){count+=stack.getCount();h.assertTrue(stack.getTag().getString("OriginalFixture").equals("preserve me"),"Original metadata lost");}h.assertTrue(count==1&&StoryItemCustody.held(s,"Key").isEmpty(),"Key returned more than once");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void stoneCustodySearchesNestedStorageWithoutTouchingOtherItems(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{var ours=stone(s);ours.getOrCreateTag().putString("MasterReceipt","same stone");var box=new ItemStack(Items.SHULKER_BOX);var entries=new ListTag();var inside=ours.save(new CompoundTag());inside.putByte("Slot",(byte)0);entries.add(inside);box.getOrCreateTagElement("BlockEntityTag").put("Items",entries);p.getInventory().setItem(0,box);var stranger=stone(s);stranger.getTag().putUUID("StoryOwner",UUID.randomUUID());p.getInventory().setItem(1,stranger);p.getInventory().setItem(2,new ItemStack(Items.EMERALD,3));h.assertTrue(StoryItemCustody.capture(p,s,"Stone",stack->StoryItemCustody.stone(stack,s)),"Nested original was not found");h.assertTrue(box.getTagElement("BlockEntityTag").getList("Items",10).isEmpty(),"Original remained inside its old container");h.assertTrue(p.getInventory().getItem(1)==stranger&&p.getInventory().getItem(2).getCount()==3,"Confiscation removed unrelated items");h.assertTrue(StoryItemCustody.held(s,"Stone").getTag().getString("MasterReceipt").equals("same stone"),"Confiscation replaced the master item");StoryItemCustody.destroy(s,"Stone");h.assertFalse(StoryItemCustody.giveBack(p,s,"Stone"),"Burned Stone was recreated");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void eyesAreThreeAuthenticCapabilitiesAndRetireIdempotently(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{h.assertFalse(RescueEyes.claim(p,s,0),"Eye obtained before defeat/discovery");for(int i=0;i<3;i++){var eye=RescueEyes.eye(s,i);eye.putBoolean("Defeated",true);eye.putBoolean("Discovered",true);h.assertTrue(RescueEyes.claim(p,s,i)&&RescueEyes.claim(p,s,i),"Eye claim not idempotent");}int count=0;for(var stack:p.getInventory().items)if(stack.is(ModItems.GHOST_EYE.get()))count+=stack.getCount();h.assertTrue(count==3&&RescueEyes.all(s),"Claim ledger cloned or omitted a child");var unrelated=new ItemStack(ModItems.GHOST_EYE.get());unrelated.getOrCreateTag().putUUID("EyeOwner",UUID.randomUUID());p.getInventory().setItem(8,unrelated);p.getInventory().setItem(9,new ItemStack(Items.EMERALD,4));h.assertTrue(RescueEyes.release(p,s)&&RescueEyes.release(p,s),"Retirement not idempotent");h.assertTrue(p.getInventory().getItem(8)==unrelated&&p.getInventory().getItem(9).getCount()==4,"Retirement removed another owner's eye or a green item");for(int i=0;i<3;i++)h.assertFalse(RescueEyes.authentic(StoryItemCustody.held(s,"RetiredEye"+i),s,i),"Retired eye still authorizes gameplay");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void propOwnerRealmAndSerialAreActuallySynchronized(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{var original=CinematicPropEntity.TYPE.get().create(p.serverLevel());var remote=CinematicPropEntity.TYPE.get().create(p.serverLevel());original.configure(s,RescueProps.EYE,2);remote.getEntityData().assignValues(original.getEntityData().getNonDefaultValues());h.assertTrue(remote.owned(s)&&remote.slot()==2,"Owner/realm only lived in unsynchronized Java fields");var saved=original.saveWithoutId(new CompoundTag());var reloaded=CinematicPropEntity.TYPE.get().create(p.serverLevel());reloaded.load(saved);h.assertTrue(reloaded.owned(s)&&reloaded.slot()==2,"Saved eye ownership changed after reload");var wrong=new VisitData.Scene();wrong.owner=UUID.randomUUID();wrong.door=s.door;wrong.loop.event.putInt("Serial",7);h.assertFalse(remote.owned(wrong),"Another owner can see/claim this prop");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void doorLockWaitsForEntirePlayerToClearThreshold(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{var scene=ParentRescueStory.data(s);scene.putBoolean("Started",true);var scenery=new CompoundTag();scenery.putLong("House",new BlockPos(500,100,500).asLong());scene.put("Scenery",scenery);var c=FirstEscapeScene.at(s,30,6,41);h.assertFalse(FirstEscapeScene.fullyInRoom(s,new AABB(c.getX()+.8,c.getY(),c.getZ(),c.getX()+1.4,c.getY()+1.8,c.getZ()+.6)),"Only the player's feet cleared the room");var inside=FirstEscapeScene.room(s);h.assertTrue(FirstEscapeScene.fullyInRoom(s,new AABB(inside.getX(),inside.getY(),inside.getZ(),inside.getX()+.6,inside.getY()+1.8,inside.getZ()+.6)),"Fully entered player cannot close the room");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void webCollisionMatchesItsSixteenthBlockHeights(GameTestHelper h){var l=h.getLevel();for(int height=1;height<=16;height++){var state=ModBlocks.STORY_WEB.get().defaultBlockState().setValue(com.coraline.block.StoryWebBlock.HEIGHT,height);var shape=state.getCollisionShape(l,h.absolutePos(BlockPos.ZERO));h.assertTrue(Math.abs(shape.bounds().maxY-height/16.)<.00001,"Web collision is not at the rendered sag height");}h.succeed();}
    @GameTest(template="empty") public static void scopedBossDamageDoesNotDisableOrdinaryRealmProtection(GameTestHelper h){var p=player(h,true);var s=OtherMotherLoop.scene(p);try{
        // A newly constructed QA player still has vanilla's join grace period.
        // End that fixture-only countdown, exactly as ordinary play has long before this chapter.
        try{var grace=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");grace.setAccessible(true);grace.setInt(p,0);}catch(ReflectiveOperationException bad){throw new IllegalStateException("Native player fixture join-grace setup failed",bad);}
        var first=FirstEscapeStory.data(s);first.putBoolean("Started",true);first.putBoolean("Complete",true);first.putString("Phase","ESCAPE_COMPLETE");ParentRescueStory.data(s).putBoolean("Started",true);var n=ParentRescueStory.data(s).getCompound("Continuation");n.putBoolean("Started",true);n.putString("Phase","MANTIS_FIGHT");ParentRescueStory.data(s).put("Continuation",n);p.setHealth(p.getMaxHealth());float before=p.getHealth();h.assertTrue(RescueCombat.eligible(p),"Owner combat phase not eligible");h.assertFalse(p.hurt(p.damageSources().magic(),4),"Ordinary damage bypassed protected realm");h.assertTrue(p.getHealth()==before,"Ordinary damage changed health");h.assertTrue(RescueCombat.harm(p,4)&&p.getHealth()<before,"Authorized boss hazard still canceled by blanket protection");p.invulnerableTime=0;h.assertFalse(p.hurt(p.damageSources().magic(),4),"Scoped hazard permit leaked after the call");n.putString("Phase","GARDEN_SEARCH");h.assertFalse(RescueCombat.harm(p,4),"A non-combat phase can inflict boss damage");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void originalStoneCanBeRecoveredFromClosedDoubleChestHalf(GameTestHelper h){
        var p=player(h,false);var s=OtherMotherLoop.scene(p);var l=p.serverLevel();var a=h.absolutePos(new BlockPos(2,2,2));var b=a.east();
        try{l.setBlock(a,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState(),2);l.setBlock(b,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState(),2);var first=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(a);var second=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(b);var original=stone(s);original.getOrCreateTag().putString("MasterReceipt","second-half original");second.setItem(4,original);first.setItem(3,new ItemStack(Items.EMERALD,7));var pair=new net.minecraft.world.CompoundContainer(first,second);var menu=net.minecraft.world.inventory.ChestMenu.sixRows(1,p.getInventory(),pair);StoryItemCustody.stored(new net.minecraftforge.event.entity.player.PlayerContainerEvent.Close(p,menu));
            h.assertTrue(ParentRescueStory.data(s).getCompound("ItemLocations").getCompound("Stone").getLong("Position")==b.asLong(),"Double chest stored the wrong block-entity half");h.assertTrue(StoryItemCustody.capture(p,s,"Stone",stack->StoryItemCustody.stone(stack,s)),"Closed double-chest original was not found");h.assertTrue(second.getItem(4).isEmpty()&&first.getItem(3).getCount()==7,"Stored original remained or unrelated contents changed");h.assertTrue(StoryItemCustody.held(s,"Stone").getTag().getString("MasterReceipt").equals("second-half original"),"Stored Stone metadata changed");
        }finally{l.setBlock(a,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);l.setBlock(b,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);clean(p);}h.succeed();
    }
    @GameTest(template="empty") public static void virtualCabinetCustodyPreservesUnrelatedSavedContents(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{var cabinet=new CompoundTag();cabinet.putString("CabinetIdentity","preserve cabinet");var items=new ListTag();var original=stone(s).save(new CompoundTag());original.putByte("Slot",(byte)4);items.add(original);var unrelated=new ItemStack(Items.EMERALD,9).save(new CompoundTag());unrelated.putByte("Slot",(byte)8);items.add(unrelated);cabinet.put("Items",items);var cabinets=new ListTag();cabinets.add(cabinet);var root=new CompoundTag();root.put("Cabinets",cabinets);s.loop.secrets.world.put("HouseCabinets",root);h.assertTrue(StoryItemCustody.capture(p,s,"Stone",stack->StoryItemCustody.stone(stack,s)),"Virtual cabinet original was missed");h.assertTrue(items.size()==1&&ItemStack.of(items.getCompound(0)).getCount()==9&&items.getCompound(0).getByte("Slot")==8,"Unrelated saved slots were changed");h.assertTrue(cabinet.getString("CabinetIdentity").equals("preserve cabinet"),"Cabinet identity reset");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void crawlPreparationKeepsJournalWhenLaterCellIsObstructed(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);var n=RescueChapter.data(s);n.putBoolean("Started",true);var l=p.server.getLevel(ActivityWorld.KEY);var blocked=RescuePassage.origin(p,s).offset(8,-1,0);try{h.assertFalse(RescuePassage.prepare(p,s),"Passage ignored its incremental preload budget");int before=n.getCompound("PassageCells").size();h.assertTrue(before>0,"First batch journal was detached");l.getChunkAt(blocked);l.setBlock(blocked,net.minecraft.world.level.block.Blocks.GOLD_BLOCK.defaultBlockState(),2);for(int i=0;i<8&&!n.contains("Blocker");i++)RescuePassage.prepare(p,s);h.assertFalse(n.getBoolean("PassageReady"),"An obstructed corridor was marked ready");h.assertTrue(n.getCompound("PassageCells").size()>=before,"Obstruction erased earlier restoration records");RescuePassage.restore(p,s);h.assertTrue(l.getBlockState(blocked).is(net.minecraft.world.level.block.Blocks.GOLD_BLOCK),"Restoration overwrote a foreign obstruction");}finally{RescuePassage.restore(p,s);l.setBlock(blocked,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);clean(p);}h.succeed();}
    @GameTest(template="empty") public static void webPreparationRejectsForeignSupportWithoutLosingJournal(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);var n=RescueChapter.data(s);n.putBoolean("Started",true);var l=p.server.getLevel(ActivityWorld.KEY);var q=RescueWebSite.at(p,s,0,200.0/RescueWebLayout.SAMPLES);var blocked=BlockPos.containing(q.x,q.y-.001,q.z);try{RescueWebSite.prepare(p,s);int before=n.getCompound("WebCells").size();h.assertTrue(before>0,"Web journal was not saved after its first batch");l.getChunkAt(blocked);l.setBlock(blocked,net.minecraft.world.level.block.Blocks.GOLD_BLOCK.defaultBlockState(),2);for(int i=0;i<12&&!n.contains("Blocker");i++)RescueWebSite.prepare(p,s);h.assertFalse(n.getBoolean("WebReady"),"Web skipped an obstruction and marked a broken route ready");h.assertTrue(n.getCompound("WebCells").size()>=before,"Web obstruction erased earlier records");RescueWebSite.restore(p,s);h.assertTrue(l.getBlockState(blocked).is(net.minecraft.world.level.block.Blocks.GOLD_BLOCK),"Web cleanup overwrote unrelated terrain");}finally{RescueWebSite.restore(p,s);l.setBlock(blocked,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);clean(p);}h.succeed();}
    @GameTest(template="empty") public static void storyCatLeaseDepartureKeepsTheSameCanonicalEntity(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);var l=p.serverLevel();var at=h.absolutePos(new BlockPos(2,2,2));try{l.setBlock(at.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);l.setBlock(at,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);l.setBlock(at.above(),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);p.setPos(at.getX()+200,at.getY(),at.getZ());var first=ShowActors.acquire(p,s,"cat",l,Vec3.atBottomCenterOf(at));h.assertTrue(first!=null,"No initial story Cat");var id=first.getUUID();h.assertTrue(ShowActors.releaseHidden(p,s,"cat"),"Hidden Cat could not finish its lease");h.assertFalse(first.isRemoved(),"Cast cleanup deleted the canonical Cat");var second=ShowActors.acquire(p,s,"cat",l,Vec3.atBottomCenterOf(at));h.assertTrue(second==first&&second.getUUID().equals(id),"A later chapter spawned another Cat");var saved=new VisitData.Scene();saved.loop=OtherMotherLoopState.load(s.loop.save());h.assertTrue(saved.loop.story.getCompound("CanonicalStoryCat").getUUID("Entity").equals(id),"Canonical Cat identity was lost on save/reload");first.discard();}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void continuationInputsRequireCurrentOwnerNonceAndValidChoice(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{var n=RescueChapter.data(s);n.putBoolean("Started",true);RescueChapter.go(p,s,RescueChapter.Phase.HIDING_CHOICE);var nonce=n.getUUID("Input");RescueChapter.input(p,UUID.randomUUID(),"behind_little_door");h.assertTrue(RescueChapter.phase(s)==RescueChapter.Phase.HIDING_CHOICE,"Stale nonce advanced the finale");RescueChapter.input(p,nonce,"garden");h.assertTrue(RescueChapter.phase(s)==RescueChapter.Phase.HIDING_CHOICE,"Disabled choice advanced the finale");n.remove("LastInput");RescueChapter.input(p,nonce,"behind_little_door");h.assertTrue(RescueChapter.phase(s)==RescueChapter.Phase.FINAL_H,"Valid current-owner choice was ignored");RescueChapter.input(p,nonce,"fight");h.assertTrue(RescueChapter.phase(s)==RescueChapter.Phase.FINAL_H,"Prior-phase nonce was replayed");var other=player(h,false);try{RescueChapter.input(other,n.getUUID("Input"),"fight");h.assertTrue(RescueChapter.phase(s)==RescueChapter.Phase.FINAL_H,"Another owner changed this finale");}finally{clean(other);}}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void motherLookupLoadsCanonicalActivityWorldBeldam(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);var l=p.server.getLevel(ActivityWorld.KEY);var at=ShowSiteData.get(p.server).center(s.owner,false).offset(150,-40,100);LoopProps.hold(l,at);var mother=ModEntities.MOM.get().create(l);mother.makeOtherParent(0);mother.setPos(Vec3.atBottomCenterOf(at));s.mom=mother.getUUID();l.addFreshEntity(mother);RescueChapter.data(s).putLong("BeldamAt",at.asLong());h.runAfterDelay(10,()->{try{h.assertTrue(ParentRescueStory.mother(p,s)==mother,"Lookup still only searched OtherWorld after the web transfer");h.assertTrue(mother.getUUID().equals(s.mom),"Canonical mother identity changed");}finally{mother.discard();clean(p);}h.succeed();});}
    @GameTest(template="empty") public static void weightedWebChangesActualCollisionAndRecoversItsRestHeight(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);var l=p.server.getLevel(ActivityWorld.KEY);var at=RescueWebSite.center(p,s).above(8);var q=new ServerPlayer(p.server,l,p.getGameProfile());q.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(q.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),q);var n=RescueChapter.data(s);n.putBoolean("Started",true);n.putBoolean("WebReady",true);var cell=new CompoundTag();cell.put("Original",NbtUtils.writeBlockState(net.minecraft.world.level.block.Blocks.AIR.defaultBlockState()));var rest=ModBlocks.STORY_WEB.get().defaultBlockState().setValue(com.coraline.block.StoryWebBlock.HEIGHT,16);cell.put("Placed",NbtUtils.writeBlockState(rest));cell.putInt("RestHeight",16);var journal=new CompoundTag();journal.put(Long.toString(at.asLong()),cell);n.put("WebCells",journal);try{l.getChunkAt(at);l.setBlock(at,rest,2);q.setPos(at.getX()+.5,at.getY()+1,at.getZ()+.5);q.setDeltaMovement(Vec3.ZERO);RescueWebSite.sag(q,s);var loaded=l.getBlockState(at);h.assertTrue(loaded.getValue(com.coraline.block.StoryWebBlock.HEIGHT)==15,"Player weight changed only a decorative mesh");h.assertTrue(Math.abs(loaded.getCollisionShape(l,at).bounds().maxY-15/16.)<.00001,"Sagged mesh and actual support height diverged");q.setPos(q.position().add(6,0,0));RescueWebSite.sag(q,s);h.assertTrue(l.getBlockState(at).getValue(com.coraline.block.StoryWebBlock.HEIGHT)==16,"Unweighted support did not recover");l.setBlock(at,net.minecraft.world.level.block.Blocks.GOLD_BLOCK.defaultBlockState(),2);RescueWebSite.sag(q,s);RescueWebSite.restore(q,s);h.assertTrue(l.getBlockState(at).is(net.minecraft.world.level.block.Blocks.GOLD_BLOCK),"Weight/cleanup overwrote a changed foreign cell");}finally{l.setBlock(at,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);clean(p);}h.succeed();}
    private RescueFoundationsGameTests(){}
}
